// ---------------------------------------------------------------------------
// mkChar / Rf_mkChar — create a CHARSXP from a null-terminated C string.
//
// Usage: rpart.c:331-344, one mkChar call per named slot of the output list:
//   SET_STRING_ELT(rname, 0, mkChar("which"));
//   SET_STRING_ELT(rname, 1, mkChar("cptable"));
//   ... (up to 7 slots)
//
// The CHARSXP node layout:
//   s->type   = CHARSXP (9)
//   s->length = strlen(str)
//   s->nrow   = strlen(str)
//   s->ncol   = 1
//   s->data   = malloc(strlen(str) + 1)   // null-terminated copy of str
//
// On allocation failure, RError is thrown (Invariant 1).
// The CHARSXP node is heap-allocated; Python-side cleanup must call
// free_sexp() on the STRSXP that holds it (which frees children).
// ---------------------------------------------------------------------------
#ifndef FAKE_MKCHAR_DEFINED
#define FAKE_MKCHAR_DEFINED

inline SEXP Rf_mkChar(const char *str) {
    size_t len = strlen(str);
    SEXPREC *s = (SEXPREC *) malloc(sizeof(SEXPREC));
    if (!s) throw RError("mkChar: out of memory allocating SEXPREC node");
    s->type   = CHARSXP;
    s->length = (int) len;
    s->nrow   = (int) len;
    s->ncol   = 1;
    s->data   = malloc(len + 1);
    if (!s->data) {
        free(s);
        throw RError("mkChar: out of memory allocating string buffer");
    }
    strcpy((char *) s->data, str);
    return s;
}

/* The real Rinternals.h maps mkChar -> Rf_mkChar via #define in many builds.
   Provide the short name as an inline to avoid double-expansion issues. */
inline SEXP mkChar(const char *str) { return Rf_mkChar(str); }

#endif // FAKE_MKCHAR_DEFINED

// ---------------------------------------------------------------------------
// VECSXP / STRSXP element accessors.
//
// VECTOR_ELT(x, i)       — read element i from a VECSXP (generic list).
// SET_VECTOR_ELT(x, i, v) — write element i; returns v (per real API).
// STRING_ELT(x, i)        — read element i from a STRSXP (string vector).
// SET_STRING_ELT(x, i, v) — write element i (no return value in real API).
//
// Usage: rpart.c:329-345
//   SEXP rlist = PROTECT(allocVector(VECSXP, nout));
//   SEXP rname = allocVector(STRSXP, nout);
//   setAttrib(rlist, R_NamesSymbol, rname);
//   SET_VECTOR_ELT(rlist, 0, which3);
//   SET_STRING_ELT(rname, 0, mkChar("which"));
//   ...
//
// For VECSXP and STRSXP, allocVector stores a SEXP[length] array in data.
// SEXP[i] is either a child SEXP (VECSXP) or a CHARSXP (STRSXP).
// After allocVector, all slots are zeroed (nullptr); they are populated by
// SET_VECTOR_ELT / SET_STRING_ELT before the list is returned.
//
// The real Rinternals.h (non-STRICT_R_HEADERS builds) defines these as
// static inline functions.  The fake uses the same pattern.
// ---------------------------------------------------------------------------
#ifndef FAKE_VECTORELT_DEFINED
#define FAKE_VECTORELT_DEFINED

inline SEXP VECTOR_ELT(SEXP s, int i) {
    return static_cast<SEXP *>(s->data)[i];
}

inline SEXP SET_VECTOR_ELT(SEXP s, int i, SEXP v) {
    static_cast<SEXP *>(s->data)[i] = v;
    return v;
}

inline SEXP STRING_ELT(SEXP s, int i) {
    return static_cast<SEXP *>(s->data)[i];
}

inline void SET_STRING_ELT(SEXP s, int i, SEXP v) {
    static_cast<SEXP *>(s->data)[i] = v;
}

#endif // FAKE_VECTORELT_DEFINED

