// ---------------------------------------------------------------------------
// R_NilValue — the NULL singleton (NILSXP).
//
// Usage: rpart.c:64
//   SEXP which3, ..., csplit3 = R_NilValue, ...;
// Usage: rpart_callback.c:71
//   return R_NilValue;
// Usage: rpart.c:329 (via setAttrib / getAttrib stubs that return it)
//
// The real Rinternals.h declares:
//   LibExtern SEXP R_NilValue;
// (a single instance in libR.so).
//
// Fake strategy: a static SEXPREC with type=NILSXP, length=0, data=NULL.
// The make_nil_value() factory guarantees a single address per translation
// unit.  Because the static local is zero-initialized before first use,
// this is safe across all include orders.
//
// NOTE: INTSXP.h does not define R_NilValue; this is the sole definition.
// The FAKE_R_NILVALUE_DEFINED guard prevents redefinition if a future
// header or master fake_R.h also defines it.
// ---------------------------------------------------------------------------
#ifndef FAKE_R_NILVALUE_DEFINED
#define FAKE_R_NILVALUE_DEFINED

inline SEXP make_nil_value() {
    static SEXPREC nil_rec = { NILSXP, 0, 0, 0, NULL };
    return &nil_rec;
}

/* R_NilValue is a static file-scope SEXP; every translation unit that
   includes this header gets a pointer to the same singleton address
   (because the static local in make_nil_value() is initialized once). */
static SEXP R_NilValue = make_nil_value();

#endif // FAKE_R_NILVALUE_DEFINED

