// ---------------------------------------------------------------------------
// PRINTNAME — returns the name SEXP (CHARSXP) for a SYMSXP.
//
// Usage: rpart_callback.c:24
//   error(_("variable '%s' not found"), CHAR(PRINTNAME(sym)));
//
// The real Rinternals.h (USE_RINTERNALS branch) accesses the symsxp.pname
// field.  In the fake, a symbol created by install() stores a CHARSXP* in
// its data field (see the 'install' fake guide).  For correctly constructed
// fake symbols, PRINTNAME(s) returns that CHARSXP*.
//
// Safety fallback: if data is NULL (e.g., for R_UnboundValue), return s
// itself.  R_CHAR on a SYMSXP with data=NULL returns "" (casting NULL to
// const char * and printing it is undefined, but R_CHAR is only called in
// the error path, so the message may be garbled — acceptable for a fatal
// diagnostic).  To avoid UB, the fallback returns R_NilValue (NILSXP,
// data=NULL).  R_CHAR on NILSXP would still be NULL; callers should treat
// the error path as best-effort only.
// ---------------------------------------------------------------------------
#ifndef FAKE_PRINTNAME_DEFINED
#define FAKE_PRINTNAME_DEFINED

inline SEXP PRINTNAME(SEXP s) {
    if (s && s->type == SYMSXP && s->data)
        return static_cast<SEXP>(s->data);
    return R_NilValue;
}

#endif // FAKE_PRINTNAME_DEFINED

