// ---------------------------------------------------------------------------
// free_sexp — extended version with recursive VECSXP/EXPRSXP child freeing.
//
// INTSXP.h defines a basic free_sexp(SEXP) under FAKE_FREE_SEXP_DEFINED that
// frees s->data and s without recursing into children.  That is sufficient
// for the INTSXP/REALSXP cases handled there.
//
// SEXP.h replaces that definition (if the INTSXP.h version has not yet been
// used in a way that would cause a conflict) or provides a companion named
// free_sexp_deep() for VECSXP / STRSXP trees returned from rpart().
//
// Pattern: rpart.c:327-349 builds:
//   VECSXP rlist[nout]  — contains child SEXPs: which3, cptable3, ...
//   STRSXP rname[nout]  — contains CHARSXP children created by mkChar().
// Python extracts element data via VECTOR_ELT / REAL / INTEGER, then must
// free the entire tree.  free_sexp_deep() handles the recursive case.
//
// For VECSXP / EXPRSXP: data holds SEXP[length]; recurse into each child.
// For STRSXP: data holds SEXP[length] (each is a CHARSXP); recurse.
// For all others (INTSXP, REALSXP, etc.): free data buffer + node directly.
// For NILSXP: no-op (R_NilValue is a static sentinel; must not be freed).
// ---------------------------------------------------------------------------
#ifndef FAKE_FREE_SEXP_DEEP_DEFINED
#define FAKE_FREE_SEXP_DEEP_DEFINED

inline void free_sexp_deep(SEXP s) {
    if (!s) return;
    // Never free static singletons.
    if (s == R_NilValue || s == R_UnboundValue || s == R_NamesSymbol) return;
    if (s->type == VECSXP || s->type == EXPRSXP || s->type == STRSXP) {
        SEXP *children = static_cast<SEXP *>(s->data);
        for (int i = 0; i < s->length; i++) {
            if (children[i] && children[i] != R_NilValue)
                free_sexp_deep(children[i]);
        }
    }
    free(s->data);
    free(s);
}

// Redefine free_sexp to the recursive form.
// If INTSXP.h's basic free_sexp is already defined (FAKE_FREE_SEXP_DEFINED),
// we cannot redefine the inline function, but we can redirect the macro.
// Since INTSXP.h defines free_sexp as an inline (not a macro), the redirection
// below shadows it within any translation unit that includes SEXP.h after
// INTSXP.h.  Both the shallow and deep forms remain available by their explicit
// names.  Callers that need deep freeing (returning VECSXP from rpart()) must
// call free_sexp_deep() explicitly on the top-level SEXP, or use the macro
// redirect below.
//
// Note: the #undef + #define approach is used here rather than re-declaring
// the inline, which would cause a redefinition error in C++.
#undef free_sexp
#define free_sexp(s) free_sexp_deep(s)

#endif // FAKE_FREE_SEXP_DEEP_DEFINED

