// ---------------------------------------------------------------------------
// --- ArenaFrame usage ---
//
// Every .Call-entry wrapper that calls rpart, xpred, pred_rpart, rpartexp2,
// or init_rpcallback must declare `ArenaFrame _frame;` as its first statement.
// These functions mix SEXP allocations (heap, not arena) with ALLOC / R_alloc
// scratch allocations (arena, freed at frame exit).
//
// Example wrapper (pred_rpart as representative):
//
//   #include "fake_arena.h"
//   extern "C" SEXP pred_rpart_entry(
//           SEXP dimx, SEXP nnode, SEXP nsplit, SEXP dimc,
//           SEXP nnum, SEXP nodes2, SEXP vnum, SEXP split2,
//           SEXP csplit2, SEXP usesur, SEXP xdata2, SEXP xmiss2) {
//       ArenaFrame _frame;   // frees all R_alloc/ALLOC scratch on exit
//       try {
//           return pred_rpart(dimx, nnode, nsplit, dimc, nnum, nodes2,
//                             vnum, split2, csplit2, usesur, xdata2, xmiss2);
//       } catch (const RError &e) {
//           // store e.what() for Python, then return sentinel
//           return R_NilValue;
//       }
//   }
//
// SEXP return values (where, rlist, predict2, keep) are heap-allocated via
// malloc() inside allocVector / allocMatrix and survive ArenaFrame
// destruction.  Python extracts data and calls free_sexp() (or
// free_sexp_deep() for VECSXP trees) after copying data into numpy arrays.
//
// Static SEXP globals (expr1, expr2, rho in rpart_callback.c) are set by
// init_rpcallback() and consumed by eval() / findVar() stubs (Category E
// items; see the 'eval', 'findVar', and 'install' fake guides).  The SEXP
// type definition here enables compilation; the interpreter paths require
// function-pointer bridges registered from Python before calling rpart()
// with method=4 (user-defined splits).
// ---------------------------------------------------------------------------

#endif // FAKE_SEXP_H
